build_history_source.source:
def build_causal_track_history(
    associated_track,
    *,
    context,
    timestamps_s: tuple[
        float,
        ...,
    ],
) -> CausalTrackHistory:
    if len(
        timestamps_s
    ) != HISTORY_STEPS:
        raise ValueError(
            "Stage4 requires 11 "
            "causal timestamps."
        )

    observations = tuple(
        cartesianize_associated_track(
            associated_track,
            context=context,
        )
    )

    if not observations:
        raise ValueError(
            "Associated track has no "
            "Cartesian observations."
        )

    by_frame = {}

    for observation in observations:
        frame_index = (
            _extract_frame_index(
                observation,
                timestamps_s=(
                    timestamps_s
                ),
            )
        )

        by_frame[
            frame_index
        ] = (
            _extract_position(
                observation
            ),
            _extract_covariance(
                observation
            ),
        )

    steps = []

    previous_position = None
    previous_timestamp = None

    for frame_index, timestamp in (
        enumerate(
            timestamps_s
        )
    ):
        if frame_index not in by_frame:
            steps.append(
                HistoryStep(
                    frame_index=frame_index,
                    timestamp_s=(
                        float(timestamp)
                    ),
                    position_H0_m=(
                        0.0,
                        0.0,
                        0.0,
                    ),
                    velocity_H0_mps=(
                        0.0,
                        0.0,
                        0.0,
                    ),
                    measurement_covariance_H0_m2=(
                        _zero_covariance()
                    ),
                    observed=False,
                    velocity_valid=False,
                )
            )

            continue

        (
            position,
            covariance,
        ) = by_frame[
            frame_index
        ]

        velocity = (
            0.0,
            0.0,
            0.0,
        )

        velocity_valid = False

        if (
            previous_position
            is not None
            and
            previous_timestamp
            is not None
        ):
            dt = (
                float(timestamp)
                -
                previous_timestamp
            )

            if dt <= 0.0:
                raise RuntimeError(
                    "Non-positive causal "
                    "velocity interval."
                )

            velocity = tuple(
                (
                    position[axis]
                    -
                    previous_position[axis]
                )
                /
                dt
                for axis in range(3)
            )

            velocity_valid = True

        steps.append(
            HistoryStep(
                frame_index=frame_index,
                timestamp_s=(
                    float(timestamp)
                ),
                position_H0_m=(
                    position
                ),
                velocity_H0_mps=(
                    velocity
                ),
                measurement_covariance_H0_m2=(
                    covariance
                ),
                observed=True,
                velocity_valid=(
                    velocity_valid
                ),
            )
        )

        previous_position = position
        previous_timestamp = float(
            timestamp
        )

    observed = [
        step
        for step in steps
        if step.observed
    ]

    latest = observed[-1]

    return CausalTrackHistory(
        prediction_id=(
            _extract_prediction_id(
                associated_track
            )
        ),
        steps=tuple(
            steps
        ),
        latest_observed_frame_index=(
            latest.frame_index
        ),
        latest_position_H0_m=(
            latest.position_H0_m
        ),
    )

build_scene_source.source:
def build_causal_scene_inputs(
    associated_tracks,
    *,
    scenario_id: str,
    context,
    timestamps_s: tuple[
        float,
        ...,
    ],
) -> CausalSceneInputs:
    histories = []

    for associated_track in (
        associated_tracks
    ):
        try:
            history = (
                build_causal_track_history(
                    associated_track,
                    context=context,
                    timestamps_s=(
                        timestamps_s
                    ),
                )
            )

        except ValueError:
            continue

        histories.append(
            history
        )

    histories.sort(
        key=lambda history:
            history.prediction_id
    )

    return CausalSceneInputs(
        scenario_id=scenario_id,
        timestamps_s=(
            timestamps_s
        ),
        histories=tuple(
            histories
        ),
    )

